import java.nio.file.*;import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
/** 保留反射查詢、數值、死亡與輸出本體，只增加 WORLD 入口與數值護欄。 */
public final class CompanionReflectionSceneMethods {
 static final String P="local/lito381/server/",A=P+"NativeCombatAttacker",H=P+"NativeCompanionReflectionScene";
 static ClassNode read(JarFile j)throws Exception{var c=new ClassNode();new ClassReader(j.getInputStream(j.getJarEntry(A+".class"))).accept(c,ClassReader.SKIP_DEBUG|ClassReader.EXPAND_FRAMES);return c;}
 static byte[] bytes(ClassNode c){var w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);return w.toByteArray();}
 static ClassNode terminal(JarFile j)throws Exception{var c=new ClassNode();new ClassReader(j.getInputStream(j.getJarEntry(P+"NativeSummonTerminalLifecycle.class"))).accept(c,ClassReader.SKIP_DEBUG|ClassReader.EXPAND_FRAMES);int count=0;for(var m:c.methods)if(m.name.equals("combatDamage"))for(var n:m.instructions)if(n instanceof MethodInsnNode v&&v.owner.equals(P+"NativePlayerCommit$Binding")&&v.name.equals("capture")){v.owner=H;count++;}if(count!=2)throw new AssertionError("two original summon ingress captures");return c;}
 static void patch(ClassNode c){int count=0;for(var m:new ArrayList<>(c.methods))if(m.name.equals("damage")||m.name.equals("companionDamage")){String name=m.name;m.name=name.equals("damage")?"nativeReflectionOriginalDamage":"nativeReflectionOriginalCompanionDamage";var q=new MethodNode(m.access,name,m.desc,null,null);q.instructions.add(new VarInsnNode(ALOAD,0));if(name.equals("damage")){q.instructions.add(new VarInsnNode(ALOAD,1));q.instructions.add(new VarInsnNode(ILOAD,2));q.instructions.add(new VarInsnNode(ALOAD,3));}else q.instructions.add(new VarInsnNode(ILOAD,1));q.instructions.add(new MethodInsnNode(INVOKESTATIC,H,name,m.desc,false));q.instructions.add(new InsnNode(name.equals("damage")?RETURN:ARETURN));c.methods.add(q);count++;}if(count!=2)throw new AssertionError("two reflection roots");var q=new MethodNode(ACC_STATIC,"nativeReflectionRef","()L"+A+"$Ref;",null,null);q.instructions.add(new FieldInsnNode(GETSTATIC,A,"reflecting","Ljava/lang/ThreadLocal;"));q.instructions.add(new MethodInsnNode(INVOKEVIRTUAL,"java/lang/ThreadLocal","get","()Ljava/lang/Object;",false));q.instructions.add(new TypeInsnNode(CHECKCAST,A+"$Ref"));q.instructions.add(new InsnNode(ARETURN));c.methods.add(q);}
 public static void main(String[]a)throws Exception{try(var j=new JarFile(a[1])){var c=read(j);patch(c);for(var value:List.of(c,terminal(j))){var b=bytes(value);if(a[0].equals("splice")){var p=Path.of(a[2]).resolve(value.name+".class");Files.createDirectories(p.getParent());Files.write(p,b);}else try(var out=new JarFile(a[2])){var q=new ClassNode();new ClassReader(out.getInputStream(out.getJarEntry(value.name+".class"))).accept(q,ClassReader.SKIP_DEBUG|ClassReader.EXPAND_FRAMES);if(!Arrays.equals(b,bytes(q)))throw new AssertionError("reflection boundary "+value.name);}}}System.out.println("PASS original damage and numeric bodies retained; exact WORLD pair/numeric wrappers, existing reflection value bridge and two owned summon ingress captures");}
}
